// Aplana los refunds de las ordenes reembolsadas y construye el payload saneado que
// consume public.ingest_refund (mismo shape que el nodo Sanitize Refund Data del WF E2).
const response = $input.first().json;
if (!response.body || !Array.isArray(response.body.orders)) {
  throw new Error(`Respuesta de Shopify sin body.orders como array (posible 429/5xx). status=${response.statusCode ?? "?"}`);
}
const orders = response.body.orders;
// Guard de truncado: refunds all-time ~18 << 250. Si llega una pagina llena, fallar
// RUIDOSAMENTE en vez de perder refunds silenciosamente (habria que paginar por Link header).
if (orders.length >= 250) {
  throw new Error(`Pagina de ordenes reembolsadas llena (${orders.length}); implementar paginacion antes de confiar en el backfill.`);
}
const sanitize = (str) => str
  ? String(str).replace(/[\x00-\x1F\x7F]/g, " ").replace(/<[^>]*>/g, "").substring(0, 5000)
  : null;
const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : 0; };

const items = [];
for (const o of orders) {
  const refunds = Array.isArray(o.refunds) ? o.refunds : [];
  for (const r of refunds) {
    const rli = Array.isArray(r.refund_line_items) ? r.refund_line_items : [];
    const adj = Array.isArray(r.order_adjustments) ? r.order_adjustments : [];
    let subtotal = 0;
    let impuesto = 0;
    const refund_line_items = rli.map((li) => {
      const li_subtotal = num(li.subtotal ?? li.subtotal_set?.shop_money?.amount);
      const li_tax = num(li.total_tax ?? li.total_tax_set?.shop_money?.amount);
      subtotal += li_subtotal;
      impuesto += li_tax;
      return {
        shopify_refund_line_item_id: li.id != null ? String(li.id) : null,
        shopify_line_item_id: li.line_item_id != null ? String(li.line_item_id) : null,
        cantidad: parseInt(li.quantity, 10) || 0,
        monto: li_subtotal,
        restock_type: li.restock_type || null,
      };
    });
    let envio = 0;
    for (const a of adj) {
      if (a.kind === "shipping_refund") envio += Math.abs(num(a.amount));
      impuesto += Math.abs(num(a.tax_amount));
    }
    items.push({ json: {
      shopify_refund_id: r.id != null ? String(r.id) : null,
      shopify_order_id: (r.order_id ?? o.id) != null ? String(r.order_id ?? o.id) : null,
      fecha_refund: r.created_at || r.processed_at || null,
      nota: sanitize(r.note),
      subtotal, impuesto, envio,
      total: subtotal + impuesto + envio,
      refund_line_items,
    } });
  }
}
if (items.length === 0) {
  // Sin refunds: emitir un item centinela para que el log de cierre corra igual.
  return [{ json: { _empty: true } }];
}
return items;
